 *
 * Suffix | Unit    | Example | DateInterval expression
 * -------|---------|---------|------------------------
 * y      | years   |   1y    | P1Y
 * mo     | months  |   3mo   | P3M
 * w      | weeks   |   2w    | P2W
 * d      | days    |  28d    | P28D
 * h      | hours   |   4h    | PT4H
 * m      | minutes |  12m    | PT12M
 * s      | seconds |  59s    | PT59S
 *
 * e. g. `1w 3d 4h 32m 23s` is converted to 10 days 4 hours 32 minutes and 23 seconds.
 *
 * Special cases:
 *  - An empty string will return a zero interval
 *  - Fractions are allowed for weeks, days, hours and minutes and will be converted
 *    and rounded to the next smaller value (caution: 0.5w = 4d)
 *
 * @param string $intervalDefinition
 *
 * @throws InvalidIntervalException
 *
 * @return static
 */
public static function fromString(string $intervalDefinition): static
{
    if (empty($intervalDefinition)) {
        return self::withOriginal(new static(0), $intervalDefinition);
    }

    $years = 0;
    $months = 0;
    $weeks = 0;
    $days = 0;
    $hours = 0;
    $minutes = 0;
    $seconds = 0;
    $milliseconds = 0;
    $microseconds = 0;

    $pattern = '/(-?\d+(?:\.\d+)?)\h*([^\d\h]*)/i';
    preg_match_all($pattern, $intervalDefinition, $parts, PREG_SET_ORDER);

    while ([$part, $value, $unit] = array_shift($parts)) {
        $intValue = (int) $value;
        $fraction = (float) $value - $intValue;

        // Fix calculation precision
        switch (round($fraction, 6)) {
            case 1:
                $fraction = 0;
                $intValue++;

                break;
            case 0:
                $fraction = 0;

                break;
        }

        switch ($unit === 'µs' ? 'µs' : strtolower($unit)) {
            case 'millennia':
            case 'millennium':
                $years += $intValue * CarbonInterface::YEARS_PER_MILLENNIUM;

                break;

